const options={...profiles,sourceVersion:'1.90.0'};
function nodes(root){const out=[],pending=[root],seen=new Set();while(pending.length){const value=pending.pop();if(!value||typeof value!=='object'||seen.has(value))continue;assert.ok(seen.size<1000000);seen.add(value);out.push(value);pending.push(...(value instanceof Map?[...value.values()]:Object.values(value)));}return out;}
function output(text){const lines=[];vm.runInNewContext(text,{console:{log:(...values)=>lines.push(values.map(String).join(' '))},process:{argv:[]}},{timeout:5000});return lines.length?lines.join('\n')+'\n':'';}
function captured(){const typesSource=readFileSync(new URL('../../rust/src/translation/types.rs',import.meta.url),'utf8'),spanSource=readFileSync(new URL('../../rust/src/translation/mod.rs',import.meta.url),'utf8');return createRustTypeRegionCompositionOriginals({typesSource,spanSource,typesNetwork:LinkNetwork.parse(typesSource,'Rust'),spanNetwork:LinkNetwork.parse(spanSource,'Rust')});}
for(const row of originals)for(const sourceVersion of ['1.90.0','1.99.0'])test('readonly/closed composition '+row.name+'/'+sourceVersion,()=>{const [major,minor]=process.versions.node.split('.').map(Number);assert.ok(major===24||major===22&&minor>=15,'uncovered Node '+process.versions.node+'; '+versions.node);const checked=checkProgram(parseRust(row.source,{...options,sourceVersion}));assert.equal(checkRustBorrowedVectorSourceRegions(checked),checked);assert.equal(output(emitJavaScript(checked).text),row.stdout);});
for(const row of refusals)test('retained mixed region boundary '+row.name,()=>{assert.equal(typeof row.compilerAccepted,'boolean');assert.throws(()=>checkProgram(parseRust(row.source,options)),error=>['type','unsupported','syntax'].includes(error.kind));});
test('actual complete original Type children and map_children compose without replacement methods',()=>{const fixture=captured();assert.equal(fixture.originals.length,3);for(const row of fixture.originals){for(const method of row.capture.methods){assert.ok(row.source.includes(method.declarationText));assert.ok(row.nativeSource.includes(method.declarationText));}assert.ok(!row.ownCrateNativeSource.includes('impl Type'));assert.equal(output(emitJavaScript(checkProgram(parseRust(row.source,options))).text),row.stdout);}});
test('actual scalar state publication retains source binder token and complete referent',()=>{const row=originals[0],checked=checkProgram(parseRust(row.source,options)),events=nodes(checked).filter(node=>node.sourceStateTransition);assert.ok(events.some(node=>node.sourceStateTransition.operation==='initialize'));for(const node of events){const facet=node.sourceStateTransition;assert.equal(facet.model,'Rust source state transition 1');assert.equal(row.source.slice(facet.binder.start,facet.binder.end),facet.binder.name);assert.deepEqual(Object.keys(facet).sort(),['binder','model','operation','position']);assert.equal(checkRustSourceStateTransition(facet,node.type,'Rust').binder.identity,facet.binder.identity);for(const change of [value=>value.operation='read',value=>value.binder.end=value.binder.start,value=>value.position.wrappers=['reference'],value=>value.revision=1]){const forged=structuredClone(facet);change(forged);assert.throws(()=>checkRustSourceStateTransition(forged,node.type,'Rust'));}}});
test('dropping real mutable initialization cannot manufacture a valid state tail',()=>{const checked=checkProgram(parseRust(originals[0].source,options));for(const node of nodes(checked))if(node.sourceStateTransition?.operation==='initialize')delete node.sourceStateTransition;assert.throws(()=>checkRustBorrowedVectorSourceRegions(checked),error=>error.kind==='type'||error.kind==='unsupported');});
test('old profile conflict remains without complete three-option successor',()=>{assert.throws(()=>parseRust(originals[0].source,{sourceVersion:'1.90.0',sourceSignatureModel:profiles.sourceSignatureModel,exclusiveSourceModel:profiles.exclusiveSourceModel}));for(const sourceVersion of ['1.89.0','1.100.0'])assert.throws(()=>parseRust(originals[0].source,{...options,sourceVersion}));});
test('real source state and retained readonly result survive typed Links and all emitters',()=>{const row=originals[0],packet=createTypedProgramLinks(row.source,'Rust',{rustSourceVersion:options.sourceVersion,rustSourceSignatureModel:profiles.sourceSignatureModel,rustExclusiveSourceModel:profiles.exclusiveSourceModel,rustFnMutSourceModel:profiles.fnMutSourceModel}),text=packet.network.toLino(),bytes=encodeLinkNetworkBinary(packet.network),targets=['JavaScript','Rust','Lean','Rocq'],baseline=Object.fromEntries(targets.map(target=>[target,emitTypedProgramLinks(packet.network,packet.root,target)]));for(const graph of [packet.network,LinkNetwork.fromLino(text),decodeLinkNetworkBinary(bytes)]){const checked=decodeTypedProgramLinks(graph,packet.root);assert.ok(nodes(checked).some(node=>node.sourceStateTransition));assert.equal(checkRustBorrowedVectorSourceRegions(checked),checked);for(const target of targets){const actual=emitTypedProgramLinks(graph,packet.root,target);assert.deepEqual(actual,baseline[target]);if(target==='JavaScript')assert.equal(output(actual.code),row.stdout);}}});

test('mutable readonly formals initialize real local storage without changing the source signature',()=>{
 const row=originals.find(value=>value.name==='mutable scalar parameter publishes local writes before returning independent input regions');assert.ok(row);const checked=checkProgram(parseRust(row.source,options)),fn=checked.declarations.get('refs');assert.equal(fn.sourceSignature.model,profiles.sourceSignatureModel);assert.equal(fn.params.length,2);assert.deepEqual(fn.sourceSignature.parameters[1].wrappers,[]);assert.deepEqual(fn.sourceSignature.result.arrayElementPosition.wrappers,['reference']);
 const initial=nodes(fn.body).filter(node=>node.sourceStateTransition?.operation==='initialize'&&node.sourceStateTransition.binder.name==='count');assert.equal(initial.length,1);const facet=initial[0].sourceStateTransition;assert.equal(row.source.slice(facet.binder.start,facet.binder.end),'count');assert.ok(facet.binder.start<row.source.indexOf('count += 1'));delete initial[0].sourceStateTransition;assert.throws(()=>checkRustBorrowedVectorSourceRegions(checked),error=>['type','unsupported'].includes(error.kind));
});

